# -*- coding: utf-8 -*-
"""dpr_rollback_v632_to_v631.py — R-1002-26 回滾程式（R-1003-2 上線前備份閘）
用法：python3 dpr_rollback_v632_to_v631.py <v632 dpr_suite.py> <輸出 v631 路徑>
印出 SHA256 db1b0b26… ✅ 即為 v631 原檔（逐位元組）。只還原三處：docstring v632 段、SUITE_VERSION、_PACK['xlrd.py']（v1 墊片）。"""
import sys, hashlib
NEW_HEAD = '"""dpr_suite.py — DPR 迴歸/迴路單檔套件（v632·1003 R-1003-2 xlrd 墊片取 Excel 快取值）\nv632（2026-10-03·**R-1003-2**·Amber 林彥博 P-1002-V6「修」）：\n  · xlrd.py FILE_VERSION 1→**2**：LibreOffice 轉檔後，凡轉檔值與 Excel 存檔快取值都是實質值（數字或非空文字）而不同者改用快取值；\n    空字串／錯誤值維持 v1 表示。成因：v1 轉檔時以建表當下重算 TODAY()，10/3 補跑 10/2 T1 表天數欄全多 1 天。\n    無真 xlrd（pypi 封鎖）→ 照 v1 走並印警示。DPR_XLS_RECALC=1 可強制 v1 行為（比對用）。\n  · _PACK 只換 xlrd.py；builder v601、快照 v579、23 棒、字典 v95、NT/NS v513、overrides v1.11、判定式一行未動。SUITE_VERSION 631 → 632（R-v556-1）。\n  · 斷言端（新棒或 0827 棒加「墊片 FILE_VERSION≥2」）排 v576 規格輪（雙落點缺口·比照 R-1001-16 明記）。\n'
OLD_HEAD = '"""dpr_suite.py — DPR 迴歸/迴路單檔套件（v631·1002 夜 R-1002-33 報延欄中越並列）\n'
NEW_PACK = "    'xlrd.py': '',"
OLD_PACK = "    'xlrd.py': '',"
src = open(sys.argv[1], encoding='utf-8').read()
assert src.count(NEW_HEAD) == 1 and src.count(NEW_PACK) == 1 and src.count('SUITE_VERSION = 632') == 1, '輸入不是 v632'
out = src.replace(NEW_HEAD, OLD_HEAD, 1).replace(NEW_PACK, OLD_PACK, 1).replace('SUITE_VERSION = 632', 'SUITE_VERSION = 631', 1)
open(sys.argv[2], 'w', encoding='utf-8').write(out)
h = hashlib.sha256(out.encode('utf-8')).hexdigest()
print(h, '✅ v631' if h.startswith('db1b0b26') else '❌ 不符')
